const det = $('Deterministic Rules').first().json.deterministic_findings || [];
const model = ($json.output || $json).findings || [];
const all = [...det, ...model];
const blocked = all.some(f => f.severity === 'block');
const warned = all.some(f => f.severity === 'warn');
return [{ json: {
  status: blocked ? 'fail' : (warned ? 'warn' : 'pass'),
  findings: all,
  blocking_findings: all.filter(f => f.severity === 'block'),
  screened_by: model.length ? ['deterministic', 'model'] : ['deterministic'],
  // The orchestrator reads this and nothing else. A 'fail' cannot be argued past downstream.
  may_proceed: !blocked
} }];
